// --- synthetic state scenarios ------------------------------------------------------

function makeIndex(items: ItemRecord[]): DoorstopIndex {
  const byUid = new Map(items.map((item) => [item.uid, item]));
  const childrenByUid = new Map<string, ItemRecord[]>();
  for (const item of items) {
    for (const link of item.links) {
      const target = byUid.get(link.uid);
      if (target === undefined) continue;
      const children = childrenByUid.get(link.uid);
      if (children !== undefined) {
        children.push(item);
      } else {
        childrenByUid.set(link.uid, [item]);
      }
    }
  }
  return {
    documents: [],
    items,
    byUid,
    byPrefix: new Map(),
    parentLinksByUid: new Map(items.map((item) => [item.uid, item.links])),
    childrenByUid,
    findings: [],
    ok: true,
    diagnostics: [],
    knownFilePaths: new Set(),
    counts: {
      suspectLinks: 0,
      unreviewedChanges: 0,
      unknownLinks: 0,
      missingReferences: 0,
      items: items.length,
      documents: 0,
    },
  };
}

describe("computeItemStates — synthetic suspect-link scenario", () => {
  const reqConfig = makeDocument({ prefix: "REQ", directoryPath: "" });
  const tstConfig = makeDocument({ prefix: "TST", parentPrefix: "REQ", directoryPath: "tests" });
  const documents = [reqConfig, tstConfig];

  const v1Stamp = computeItemStamp(
    { uid: "REQ001", text: "v1", ref: "", links: [], attributes: {} },
    reqConfig,
    true,
  );

  const req001 = makeItem({
    uid: "REQ001",
    documentPrefix: "REQ",
    path: "REQ001.yml",
    text: "v1",
    reviewed: v1Stamp,
  });
  const tst001 = makeItem({
    uid: "TST001",
    documentPrefix: "TST",
    path: "tests/TST001.yml",
    text: "verify v1",
    links: [{ uid: "REQ001", fingerprint: v1Stamp }],
  });

  function indexForScenario(): DoorstopIndex {
    const index = makeIndex([req001, tst001]);
    index.documents = documents;
    index.byPrefix = new Map(documents.map((document) => [document.prefix, document]));
    return index;
  }

  it("sees no suspect links while the recorded fingerprint matches the parent stamp", () => {
    const index = indexForScenario();
    computeItemStates(index);
    expect(index.byUid.get("TST001")!.stateKeys).toContain("unreviewed");
    expect(index.byUid.get("TST001")!.stateKeys).not.toContain("suspect-link");
    expect(index.byUid.get("REQ001")!.stateKeys).toContain("reviewed");
    expect(index.counts.suspectLinks).toBe(0);
    expect(index.counts.unreviewedChanges).toBe(1);
  });

  it("flags the child suspect when the parent's text changes after recording", () => {
    req001.text = "v2"; // the shared object is mutated, exactly like a workspace edit
    const index = indexForScenario();
    computeItemStates(index);

    expect(index.byUid.get("TST001")!.stateKeys).toContain("suspect-link");
    expect(index.byUid.get("REQ001")!.stateKeys).toContain("unreviewed");
    expect(index.findings).toContainEqual(
      expect.objectContaining({ severity: "warning", uid: "TST001", message: "suspect link: REQ001" }),
    );
    expect(index.findings).toContainEqual(
      expect.objectContaining({ severity: "warning", uid: "REQ001", message: "unreviewed changes" }),
    );
    expect(index.counts.suspectLinks).toBe(1);
    expect(index.counts.unreviewedChanges).toBe(2);
    // and recomputation is stable
    const chips = index.items.map((item) => [...item.stateKeys]);
    computeItemStates(index);
    expect(index.items.map((item) => [...item.stateKeys])).toEqual(chips);
  });
});

describe("computeItemStates — re-running over a changed index drops stale findings", () => {
  it("removes a stale suspect-link finding once the recorded fingerprint matches again", () => {
    const reqConfig = makeDocument({ prefix: "REQ", directoryPath: "" });
    const tstConfig = makeDocument({ prefix: "TST", parentPrefix: "REQ", directoryPath: "tests" });
    const documents = [reqConfig, tstConfig];

    const v1Stamp = computeItemStamp(
      { uid: "REQ001", text: "v1", ref: "", links: [], attributes: {} },
      reqConfig,
      true,
    );
    const req001 = makeItem({
      uid: "REQ001",
      documentPrefix: "REQ",
      path: "REQ001.yml",
      text: "v1",
      reviewed: v1Stamp,
    });
    const tst001 = makeItem({
      uid: "TST001",
      documentPrefix: "TST",
      path: "tests/TST001.yml",
      text: "verify",
      links: [{ uid: "REQ001", fingerprint: v1Stamp }],
    });
    const index = makeIndex([req001, tst001]);
    index.documents = documents;
    index.byPrefix = new Map(documents.map((document) => [document.prefix, document]));

    computeItemStates(index);
    expect(index.findings.filter((f) => f.message.startsWith("suspect link"))).toHaveLength(0);

    // parent edited → the child's recorded fingerprint goes stale → suspect
    req001.text = "v2";
    computeItemStates(index);
    expect(index.findings).toContainEqual(
      expect.objectContaining({ severity: "warning", uid: "TST001", message: "suspect link: REQ001" }),
    );
    expect(index.counts.suspectLinks).toBe(1);

    // parent reverted on the SAME index object (no model-chain re-run) — the
    // stale suspect finding must NOT survive the re-run
    req001.text = "v1";
    computeItemStates(index);
    expect(index.findings.filter((f) => f.message.startsWith("suspect link"))).toHaveLength(0);
    expect(index.counts.suspectLinks).toBe(0);
  });

  it("removes a stale 'needs initial review' finding after the item is reviewed", () => {
    const reqConfig = makeDocument({ prefix: "REQ", directoryPath: "" });
    const documents = [reqConfig];
    const req001 = makeItem({
      uid: "REQ001",
      documentPrefix: "REQ",
      path: "REQ001.yml",
      text: "v1",
      reviewed: null,
    });
    const index = makeIndex([req001]);
    index.documents = documents;
    index.byPrefix = new Map(documents.map((document) => [document.prefix, document]));

    computeItemStates(index);
    expect(index.findings).toContainEqual(
      expect.objectContaining({ severity: "info", message: "needs initial review" }),
    );

    // `doorstop review` between runs updates ItemRecord.reviewed — the stale
    // info finding must disappear and the chip must flip to "reviewed"
    req001.reviewed = computeItemStamp(
      { uid: "REQ001", text: "v1", ref: "", links: [], attributes: {} },
      reqConfig,
      true,
    );
    computeItemStates(index);
    expect(index.findings.filter((f) => f.message.startsWith("needs initial review"))).toHaveLength(0);
    expect(index.byUid.get("REQ001")!.stateKeys).toContain("reviewed");
  });
});

describe("computeItemStates — childrenByUid child-document scoping", () => {
  it("ignores same-document links when deciding no-child-links", () => {
    const parentDoc = makeDocument({ prefix: "SYS", directoryPath: "sys" });
    const childDoc = makeDocument({ prefix: "TST", parentPrefix: "SYS", directoryPath: "tests" });
    const documents = [parentDoc, childDoc];

    const sys001 = makeItem({ uid: "SYS001", documentPrefix: "SYS", path: "sys/SYS001.yml", text: "parent" });
    const sys002 = makeItem({
      uid: "SYS002",
      documentPrefix: "SYS",
      path: "sys/SYS002.yml",
      text: "links to SYS001 from the SAME document",
      links: [{ uid: "SYS001", fingerprint: null }],
    });
    const tst001 = makeItem({
      uid: "TST001",
      documentPrefix: "TST",
      path: "tests/TST001.yml",
      text: "links to SYS002 from the child document",
      links: [{ uid: "SYS002", fingerprint: null }],
    });

    const index = makeIndex([sys001, sys002, tst001]);
    index.documents = documents;
    index.byPrefix = new Map(documents.map((document) => [document.prefix, document]));
    computeItemStates(index);

    // SYS001: only same-document links → still no child links
    expect(index.byUid.get("SYS001")!.stateKeys).toContain("no-child-links");
    // SYS002: has a child-document (TST) link → no chip
    expect(index.byUid.get("SYS002")!.stateKeys).not.toContain("no-child-links");
  });
});